description:
Work with the raw bytes of values the correct way, with `std::memcpy` or `std::bit_cast` instead of pointer casts:

```cpp
std::uint32_t floatBits(float f);
float floatFromBits(std::uint32_t bits);
std::uint32_t byteSwap32(std::uint32_t v);
std::uint32_t readBigEndian32(const unsigned char* bytes);
std::uint32_t readUnaligned32(const unsigned char* buffer, std::size_t offset);
```

- **floatBits** returns the 32 bits of a `float`, and **floatFromBits** turns bits back into a `float`.
- **byteSwap32** reverses the order of the four bytes: `0x11223344` becomes `0x44332211`.
- **readBigEndian32** reads four bytes that are in big-endian order (most significant first), as network protocols send them. Build the number with shifts so it works on any machine.
- **readUnaligned32** reads a number in this machine's own byte order from any offset of a buffer, even an odd one. Copy the bytes; do not cast `buffer + offset` to a `std::uint32_t*`.

starter.solution.cpp:
#include <cstddef>
#include <cstdint>

std::uint32_t floatBits(float f) { return 0; }
float floatFromBits(std::uint32_t bits) { return 0.0f; }
std::uint32_t byteSwap32(std::uint32_t v) { return v; }
std::uint32_t readBigEndian32(const unsigned char* bytes) { return 0; }
std::uint32_t readUnaligned32(const unsigned char* buffer, std::size_t offset) { return 0; }

solution.solution.cpp:
#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstring>

std::uint32_t floatBits(float f) { return std::bit_cast<std::uint32_t>(f); }

float floatFromBits(std::uint32_t bits) { return std::bit_cast<float>(bits); }

std::uint32_t byteSwap32(std::uint32_t v)
{
    return (v >> 24) | ((v >> 8) & 0x0000FF00u) | ((v << 8) & 0x00FF0000u) | (v << 24);
}

std::uint32_t readBigEndian32(const unsigned char* bytes)
{
    return (static_cast<std::uint32_t>(bytes[0]) << 24) | (static_cast<std::uint32_t>(bytes[1]) << 16)
         | (static_cast<std::uint32_t>(bytes[2]) << 8) | static_cast<std::uint32_t>(bytes[3]);
}

std::uint32_t readUnaligned32(const unsigned char* buffer, std::size_t offset)
{
    std::uint32_t value;
    std::memcpy(&value, buffer + offset, sizeof(value));
    return value;
}

unitTests:
TEST("float bits") {
    CHECK_EQ(floatBits(1.0f), 0x3F800000u);
    CHECK_EQ(floatBits(-2.5f), 0xC0200000u);
    CHECK_EQ(floatBits(0.0f), 0u);
    CHECK_EQ(floatFromBits(0x40490FDBu), 3.14159274f);
    CHECK_EQ(floatFromBits(floatBits(123.25f)), 123.25f);
}
TEST("byte swap") {
    CHECK_EQ(byteSwap32(0x11223344u), 0x44332211u);
    CHECK_EQ(byteSwap32(0x000000FFu), 0xFF000000u);
    CHECK_EQ(byteSwap32(byteSwap32(0xDEADBEEFu)), 0xDEADBEEFu);
}
TEST("big-endian reads") {
    const unsigned char net[]{ 0x00, 0x00, 0x01, 0xBB, 0xC0, 0xA8, 0x00, 0x01 };
    CHECK_EQ(readBigEndian32(net), 443u);
    CHECK_EQ(readBigEndian32(net + 4), 0xC0A80001u);
}
TEST("unaligned reads") {
    unsigned char buffer[12]{};
    const std::uint32_t value{ 0xCAFEF00Du };
    std::memcpy(buffer + 3, &value, 4);
    CHECK_EQ(readUnaligned32(buffer, 3), 0xCAFEF00Du);
    std::memcpy(buffer + 7, &value, 4);
    CHECK_EQ(readUnaligned32(buffer, 7), 0xCAFEF00Du);
    const unsigned char zeros[5]{};
    CHECK_EQ(readUnaligned32(zeros, 1), 0u);
}

